export interface OrderDTO {
  id: string;
  items: { sku: string; qty: number; price: number }[];
  customerId: string;
}

export function calculateOrderTotal(order: OrderDTO) {
  return order.items.reduce((s, i) => s + i.qty * i.price, 0);
}

// calculateOrderTotal is used in multiple modules

// Version A
export type InvoiceData = { items: { price: number; qty: number }[]; taxRate: number };
export function invoiceTotal(data: InvoiceData) {
  return data.items.reduce((s, i) => s + i.price * i.qty, 0) * (1 + data.taxRate);
}
// InvoiceData passed around and totals computed in many modules

// Version B
export class Invoice {
  constructor(private items: { price: number; qty: number }[], private taxRate: number) {}
  total() { return this.items.reduce((s, i) => s + i.price * i.qty, 0) * (1 + this.taxRate); }
}
// Invoice instances carry their own behavior
